/*
 * A042580  Numerators of continued fraction convergents to sqrt(819).
 * https://oeis.org/A042580
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 9, u32 n <= 26, u64 n <= 52, u128 n <= 109,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function returns the nth numerator of the convergents to sqrt(819).
 * Recurrence: let a₀ = floor(sqrt(819)) = 28.  The continued fraction
 * expansion of sqrt(819) is generated by:
 *        m_{k+1} = d_k*a_k - m_k
 *        d_{k+1} = (819 - m_{k+1}²) / d_k
 *        a_{k+1} = floor((a₀ + m_{k+1}) / d_{k+1})
 * with m₀ = 0, d₀ = 1.  The convergent numerators p_k satisfy
 *        p₋₁ = 1, p₋₂ = 0,  p_k = a_k * p_{k-1} + p_{k-2}   (k ≥ 0).
 * The function returns p_n, with p₀ = 28.
 *
 * It caches computed values to handle arbitrary ordering of calls and
 * ensures O(n) total time for repeated calls up to the largest requested
 * index.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* constants for sqrt(819) */
    const uint64_t D   = 819ULL;
    const uint64_t a0  = 28ULL;      /* floor(sqrt(819)) */

    static seq_t *P = NULL;
    static size_t cap = 0;
    static idx_t  max_computed = 0;  /* highest index that has been computed */

    /* continued fraction state: works for all steps after P[max_computed] */
    static uint64_t m = 0;
    static uint64_t d = 1;
    static uint64_t a_cur = a0;   /* a_k for the step that produced P[max_computed] */

    /* Ensure storage for at least index 0 */
    if (cap == 0)
    {
        cap = 16;
        P = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!P) return (seq_t)0;      /* out of memory, return 0 */
        P[0] = (seq_t)a0;
        max_computed = 0;
    }

    if (n <= max_computed)
        return P[n];

    /* Grow storage if needed */
    if ((size_t)(n + 1) > cap)
    {
        size_t newcap = cap;
        while ((size_t)(n + 1) > newcap) newcap <<= 1;
        seq_t *tmp = (seq_t *)realloc(P, newcap * sizeof(seq_t));
        if (!tmp) return (seq_t)0;   /* out of memory */
        P = tmp;
        cap = newcap;
    }

    /* Generate successive terms */
    for (idx_t i = max_computed + 1; i <= n; ++i)
    {
        /* generate next continued fraction term */
        uint64_t m_next = a_cur * d - m;
        uint64_t d_next = (D - m_next * m_next) / d;
        uint64_t a_next = (a0 + m_next) / d_next;

        /* compute numerator using recurrence */
        if (i == 1)
        {
            /* p₁ = a₁ * p₀ + p₋₁ = a₁*28 + 1 */
            P[1] = (seq_t)a_next * P[0] + (seq_t)1;
        }
        else
        {
            P[i] = (seq_t)a_next * P[i-1] + P[i-2];
        }

        /* update state for next iteration */
        m = m_next;
        d = d_next;
        a_cur = a_next;
    }

    max_computed = n;
    return P[n];
}
